// Validates email content for forbidden keywords or required terms
// Expects input: { "subject": "...", "body": "..." }
// El webhook entrega los datos en json.query (GET) o json.body (POST),
// no en la raiz del item.
const inJson = $input.first().json;
const has = (o) => o && typeof o === 'object' && Object.keys(o).length > 0;
const src = has(inJson.query) ? inJson.query : (has(inJson.body) ? inJson.body : inJson);
const subject = src.subject || "";
const body = src.body || "";

const forbiddenKeywords = ["spam", "buy now", "click here"];
const requiredKeywords = ["invoice", "project"];

let issues = [];

forbiddenKeywords.forEach(word => {
  if (subject.toLowerCase().includes(word) || body.toLowerCase().includes(word)) {
    issues.push(`Contains forbidden keyword: ${word}`);
  }
});

// Example logic: must contain at least one required keyword if strict mode
// For now just flagging

return {
  json: {
    subject,
    bodyLength: body.length,
    issues,
    isValid: issues.length === 0
  }
};
